/* @lc app=leetcode id=3529 lang=kotlin */ class Solution { fun z(t: String): IntArray = IntArray(t.length).also { z -> (1 until t.length).fold(0 to 0) { (l, r), i -> (if (i < r) minOf(r - i, z[i - l]) else 0).let { k0 -> (k0 + generateSequence(k0) { it + 1 }.takeWhile { i + it < t.length && t[it] == t[i + it] }.count()).let { k -> z.set(i, k).let { if (i + k > r) i to i + k else l to r } } } } } fun cov(txt: String, p: String): BooleanArray = z(p + "#" + txt).let { zz -> IntArray(txt.length + 1).let { df -> txt.indices.filter { zz[p.length + 1 + it] >= p.length }.forEach { df.set(it, df[it] + 1).let { _ -> df[it + p.length]-- } }.let { df.runningFold(0) { a, b -> a + b }.drop(1).map { it > 0 }.toBooleanArray() } } } fun countCells(grid: Array<CharArray>, pattern: String): Int = grid.size.let { m -> grid[0].size.let { n -> cov(grid.joinToString("") { String(it) }, pattern).let { ch -> cov((0 until n).joinToString("") { j -> grid.map { it[j] }.joinToString("") }, pattern).let { cv -> (0 until m * n).count { c -> ch[c] && cv[(c % n) * m + c / n] } } } } } }